/* Minimal Desktop - "store" package manager with embedded initrd repository
 *
 * Repository format (generated by tools/gen_store.py):
 *   store.img : Multiboot2 module, MDSTORE1 archive with fixed-size entries
 *               followed by verified MDMOD1 module images.
 * Install path: HTTP repository first (when the network is up), local archive
 * fallback. Installed module images are unpacked into /usr/packages.
 */
#include "store.h"
#include "multiboot2.h"
#include "console.h"
#include "string.h"
#include "mm.h"
#include "ramfs.h"
#include "task.h"
#include "pit.h"
#include "net.h"

static store_archive_hdr_t *archive_hdr;
static store_pkg_t packages[STORE_MAX_PACKAGES];
static int package_count;
static bool store_ready;
static char repo_url[128] = "http://10.0.2.2:8000/store";
static char last_source[16] = "embedded";
static u8 http_buffer[49152];

static u32 fnv(const u8 *data, u32 len) { return fnv1a(data, len); }

static bool module_image_valid(const u8 *data, u32 len, const char *name) {
    if (!data || len < sizeof(store_module_hdr_t) + 8) return false;
    const store_module_hdr_t *h = (const store_module_hdr_t *)data;
    if (memcmp(h->magic, MODULE_MAGIC, 7) != 0) return false;
    if (h->version != 1) return false;
    if (h->body_size > len - sizeof(store_module_hdr_t)) return false;
    if (fnv(data + sizeof(store_module_hdr_t), h->body_size) != h->body_checksum) return false;
    char n[17];
    memcpy(n, h->name, 16);
    n[16] = 0;
    if (name && strncmp(n, name, 16) != 0) return false;
    return true;
}

bool store_init(void) {
    store_ready = false;
    package_count = 0;
    memset(packages, 0, sizeof(packages));

    if (!g_boot.has_store_module || !g_boot.store_start || g_boot.store_end <= g_boot.store_start)
        return false;

    u32 mod_size = g_boot.store_end - g_boot.store_start;
    if (mod_size < sizeof(store_archive_hdr_t)) return false;

    archive_hdr = (store_archive_hdr_t *)g_boot.store_start;
    if (memcmp(archive_hdr->magic, STORE_MAGIC, 8) != 0) return false;
    if (archive_hdr->version != 1 || archive_hdr->count > STORE_MAX_PACKAGES) return false;
    if (archive_hdr->total_size > mod_size) return false;

    store_archive_entry_t *entries =
        (store_archive_entry_t *)(g_boot.store_start + sizeof(store_archive_hdr_t));
    u32 entry_bytes = archive_hdr->count * sizeof(store_archive_entry_t);
    if (sizeof(store_archive_hdr_t) + entry_bytes > archive_hdr->total_size) return false;
    if (fnv((const u8 *)entries, entry_bytes) != archive_hdr->checksum) return false;

    for (u32 i = 0; i < archive_hdr->count; i++) {
        const store_archive_entry_t *e = &entries[i];
        if (e->offset + e->size > archive_hdr->total_size) return false;
        if (e->size < sizeof(store_module_hdr_t)) return false;
        const u8 *data = (const u8 *)(g_boot.store_start + e->offset);
        if (fnv(data, e->size) != e->checksum) return false;
        if (!module_image_valid(data, e->size, e->name)) return false;

        store_pkg_t *p = &packages[package_count++];
        memcpy(p->name, e->name, 16);
        p->name[15] = 0;
        memcpy(p->version, e->version, 12);
        p->version[11] = 0;
        memcpy(p->category, e->category, 12);
        p->category[11] = 0;
        memcpy(p->desc, e->desc, 64);
        p->desc[63] = 0;
        p->entry = e->entry;
        p->size = e->size;
        p->checksum = e->checksum;
        p->data = data;
        p->installed = false;
        p->task_pid = -1;
        strncpy(p->source, "embedded", sizeof(p->source) - 1);
    }
    store_ready = package_count > 0;
    return store_ready;
}

int store_package_count(void) { return package_count; }

store_pkg_t *store_get(int index) {
    return (index >= 0 && index < package_count) ? &packages[index] : NULL;
}

store_pkg_t *store_find(const char *name) {
    if (!name) return NULL;
    for (int i = 0; i < package_count; i++)
        if (strcasecmp(packages[i].name, name) == 0) return &packages[i];
    return NULL;
}

bool store_installed(const char *name) {
    store_pkg_t *p = store_find(name);
    return p && p->installed;
}

void store_list(void) {
    if (!store_ready) {
        kprintf("store: repository not mounted (missing Multiboot2 store module)\n");
        return;
    }
    kprintf("Minimal Store - %d packages, repository: %s\n",
            package_count, repo_url);
    kprintf("  S  PACKAGE           VERSION   SIZE      CATEGORY   DESCRIPTION\n");
    kprintf("  -  ----------------  --------  --------  ---------  --------------------\n");
    for (int i = 0; i < package_count; i++) {
        store_pkg_t *p = &packages[i];
        kprintf("  %c  %-16s  %-8s  %6u B  %-9s  %s\n",
                p->installed ? '*' : ' ', p->name, p->version, p->size,
                p->category, p->desc);
    }
    kprintf("  (* = installed)  use: store install <package>\n");
}

void store_info(const char *name) {
    store_pkg_t *p = store_find(name);
    if (!p) { kprintf("store: package '%s' not found\n", name ? name : ""); return; }
    kprintf("Package : %s %s\n", p->name, p->version);
    kprintf("Category: %s\n", p->category);
    kprintf("Size    : %u bytes\n", p->size);
    kprintf("Entry   : module #%u\n", p->entry);
    kprintf("Checksum: %08x (FNV-1a)\n", p->checksum);
    kprintf("Status  : %s\n", p->installed ? "installed" : "available");
    kprintf("Source  : %s\n", p->installed ? p->source : "embedded archive / HTTP mirror");
    kprintf("About   : %s\n", p->desc);
}

static bool http_fetch_package(const char *name, const u8 **out, u32 *out_len) {
    if (!net_is_up()) return false;
    char url[192];
    ksnprintf(url, sizeof(url), "%s/%s.mdp", repo_url, name);
    int len = 0;
    kprintf("  [net] GET %s\n", url);
    int rc = net_http_get(url, (char *)http_buffer, sizeof(http_buffer), &len);
    if (rc != 0 || len <= 0) return false;
    if (!module_image_valid(http_buffer, (u32)len, name)) {
        kprintf("  [net] downloaded module failed checksum/signature\n");
        return false;
    }
    *out = http_buffer;
    *out_len = (u32)len;
    return true;
}

static void progress_bar(const char *label, u32 total, u32 done) {
    int cells = 18;
    int fill = total ? (int)((u64)done * cells / total) : cells;
    if (fill > cells) fill = cells;
    kprintf("\r  %-12s [", label);
    for (int i = 0; i < cells; i++) kprintf(i < fill ? "#" : ".");
    kprintf("] %3d%%", total ? (int)((u64)done * 100 / total) : 100);
}

int store_install(const char *name) {
    if (!store_ready) {
        kprintf("store: repository not mounted\n");
        return -1;
    }
    store_pkg_t *p = store_find(name);
    if (!p) {
        kprintf("store: package '%s' not found. Try 'store list'.\n", name ? name : "");
        return -1;
    }
    if (p->installed) {
        kprintf("store: %s %s is already installed\n", p->name, p->version);
        return 0;
    }

    const u8 *image = p->data;
    u32 image_len = p->size;
    const char *source = "embedded";
    if (net_is_up()) {
        const u8 *remote = NULL;
        u32 remote_len = 0;
        if (http_fetch_package(p->name, &remote, &remote_len)) {
            image = remote;
            image_len = remote_len;
            source = "http";
        } else {
            kprintf("  [net] mirror unavailable, falling back to embedded archive\n");
        }
    } else {
        kprintf("  [net] network offline, using embedded archive\n");
    }

    if (!module_image_valid(image, image_len, p->name)) {
        kprintf("store: module validation failed for %s\n", p->name);
        return -1;
    }

    kprintf("\nInstalling %s %s (%u bytes, %s)\n", p->name, p->version, image_len, source);
    for (u32 step = 0; step <= image_len; step += 256) {
        u32 d = step > image_len ? image_len : step;
        progress_bar("unpacking", image_len, d);
        pit_sleep_ms(4);
    }
    progress_bar("unpacking", image_len, image_len);
    kprintf("\n");

    char path[96];
    ksnprintf(path, sizeof(path), "/usr/packages/%s.mdp", p->name);
    if (ramfs_lookup(path)) ramfs_unlink(path);
    fs_node_t *f = ramfs_create(path, FS_FILE);
    if (!f) {
        kprintf("store: cannot create %s\n", path);
        return -1;
    }
    if (ramfs_write(f, image, image_len, 0) != (int)image_len) {
        kprintf("store: short write to %s\n", path);
        ramfs_unlink(path);
        return -1;
    }

    p->installed = true;
    strncpy(p->source, source, sizeof(p->source) - 1);
    p->source[sizeof(p->source) - 1] = 0;
    strncpy(last_source, source, sizeof(last_source) - 1);

    p->task_pid = task_register(p->name, image_len / 1024 + 96, true);
    if (p->task_pid > 0) task_set_state(p->task_pid, "loaded");

    kprintf("  [PASS] checksum verified: %08x\n", fnv(image, image_len));
    kprintf("  [ OK ] registered module #%u, unpacked to %s\n", p->entry, path);
    if (p->entry == MOD_ENTRY_SNAKE) kprintf("  Run it with: snake\n");
    else if (p->entry == MOD_ENTRY_PONG) kprintf("  Run it with: pong\n");
    else if (p->entry == MOD_ENTRY_DESKTOP) kprintf("  Run it with: startgui\n");
    else if (p->entry == MOD_ENTRY_DOOM) kprintf("  Run it with: doom\n");
    else if (p->entry == MOD_ENTRY_MINILAND) kprintf("  Run it with: miniland\n");
    return 0;
}

int store_remove(const char *name) {
    store_pkg_t *p = store_find(name);
    if (!p) { kprintf("store: package '%s' not found\n", name ? name : ""); return -1; }
    if (!p->installed) { kprintf("store: %s is not installed\n", p->name); return -1; }
    char path[96];
    ksnprintf(path, sizeof(path), "/usr/packages/%s.mdp", p->name);
    ramfs_unlink(path);
    if (p->task_pid > 0) task_unregister(p->task_pid);
    p->task_pid = -1;
    p->installed = false;
    strncpy(p->source, "embedded", sizeof(p->source) - 1);
    kprintf("store: removed %s\n", p->name);
    return 0;
}

bool store_validate_all(char *err, int errlen) {
    if (!store_ready) {
        ksnprintf(err, errlen, "store archive not mounted or checksum invalid");
        return false;
    }
    if (package_count < 5) {
        ksnprintf(err, errlen, "expected >=5 packages, found %d", package_count);
        return false;
    }
    const char *required[5] = { "snake", "pong", "minimal-desktop", "doom", "miniland" };
    for (int r = 0; r < 5; r++) {
        store_pkg_t *p = store_find(required[r]);
        if (!p) {
            ksnprintf(err, errlen, "required package '%s' missing", required[r]);
            return false;
        }
        if (!module_image_valid(p->data, p->size, p->name)) {
            ksnprintf(err, errlen, "%s: module image invalid", p->name);
            return false;
        }
        if (fnv(p->data, p->size) != p->checksum) {
            ksnprintf(err, errlen, "%s: archive checksum mismatch", p->name);
            return false;
        }
        if (p->size < 256 || p->entry < 1 || p->entry > 5) {
            ksnprintf(err, errlen, "%s: manifest fields invalid", p->name);
            return false;
        }
    }
    return true;
}

const char *store_repo_url(void) { return repo_url; }
const char *store_last_source(void) { return last_source; }

bool store_module_bound(int entry) {
    for (int i = 0; i < package_count; i++)
        if (packages[i].entry == (u32)entry) return packages[i].installed;
    return false;
}

int cmd_store(int argc, char **argv) {
    if (argc < 2) {
        kprintf("Minimal Store %s\n", OS_VERSION);
        kprintf("usage: store list | install <pkg> | remove <pkg> | info <pkg> | repo [url]\n");
        kprintf("       minipacket -I <pkg> | minipacket list\n");
        kprintf("       store sources | status\n");
        return 0;
    }
    const char *sub = argv[1];
    if (strcasecmp(sub, "list") == 0 || strcasecmp(sub, "ls") == 0) {
        store_list();
        return 0;
    }
    if (strcasecmp(sub, "install") == 0 || strcasecmp(sub, "fetch") == 0 ||
        strcmp(sub, "-I") == 0 || strcmp(sub, "-i") == 0 || strcmp(sub, "-I") == 0) {
        if (argc < 3) { kprintf("usage: minipacket -I <package>  (or: store install <package>)\n"); return -1; }
        return store_install(argv[2]);
    }
    if (strcasecmp(sub, "remove") == 0 || strcasecmp(sub, "uninstall") == 0) {
        if (argc < 3) { kprintf("usage: store remove <package>\n"); return -1; }
        return store_remove(argv[2]);
    }
    if (strcasecmp(sub, "info") == 0) {
        if (argc < 3) { kprintf("usage: store info <package>\n"); return -1; }
        store_info(argv[2]);
        return 0;
    }
    if (strcasecmp(sub, "repo") == 0) {
        if (argc >= 3) {
            strncpy(repo_url, argv[2], sizeof(repo_url) - 1);
            repo_url[sizeof(repo_url) - 1] = 0;
            kprintf("store: repository set to %s\n", repo_url);
        } else {
            kprintf("repository: %s\n", repo_url);
        }
        return 0;
    }
    if (strcasecmp(sub, "sources") == 0) {
        kprintf("HTTP repository : %s\n", repo_url);
        kprintf("Local fallback  : embedded Multiboot2 store archive (%u packages)\n", package_count);
        kprintf("Last install    : via %s\n", last_source);
        return 0;
    }
    if (strcasecmp(sub, "status") == 0) {
        int n = 0;
        for (int i = 0; i < package_count; i++) if (packages[i].installed) n++;
        kprintf("store: %s, %d available, %d installed, HTTP mirror %s\n",
                store_ready ? "mounted" : "unmounted", package_count, n,
                net_is_up() ? "reachable" : "offline");
        kprintf("repo: %s\n", repo_url);
        return 0;
    }
    kprintf("store: unknown subcommand '%s'\n", sub);
    return -1;
}
